-- Seed convocatoria_content for torneoid=346 from previous mockData (V Torneo Anual Terralta 2026).
-- Safe to re-run: uses ON DUPLICATE KEY UPDATE on (torneoid, section_id).

INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'descripcion', 'text', 'Descripción', '{"text": "Terralta A.C. celebra su V Torneo Anual de Invitación edición 2026, que se llevará a cabo del 26 de Junio al 4 de Julio en las instalaciones del Club.\\n\\nLa inscripción al Torneo Anual incluye: Kit de bienvenida, Torneo de Putt Damas y Caballeros, Torneo de Approach Mixto, Torneo de Driver de Precisión Damas, Torneo de Driver de Distancia Caballeros, Torneo de Long Driver Caballeros, Premios de O´yes y alimentos/bebidas en los centros de consumo (Jugador y Cónyuge).\\n\\nPremio de Hole In One: $1,000,000 MXN al primer Hole In One en cualquiera de los 5 hoyos par 3. En caso de no haber Hole In One durante el torneo, el premio será rifado entre los jugadores inscritos al cierre de la Ceremonia de Premiación del 4 de Julio de 2026 (indispensable estar presente)."}', 1, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title = VALUES(title),
  content = VALUES(content),
  sort_order = VALUES(sort_order),
  enabled = VALUES(enabled);

INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'premiacion', 'premiacion', 'Premiación', '{"items": [{"categoria": "Caballeros", "premios": ["Campeonato, Premier, AA, A, B, C y D — 1°, 2° y 3° lugar (trofeos institucionales)."]}, {"categoria": "Seniors / Super Seniors", "premios": ["1°, 2° y 3° lugar de cada categoría."]}, {"categoria": "Damas — 1ª Categoría", "premios": ["1er lugar Gross", "1°, 2° y 3° lugar Neto"]}, {"categoria": "Damas — 2ª, 3ª, 4ª y Estrellal", "premios": ["1°, 2° y 3° lugar Neto"]}, {"categoria": "Hole In One", "premios": ["$1,000,000 MXN al primer Hole In One en cualquiera de los 5 par 3 (hoyos 3, 5, 7, 12 y 16).", "Hoyo 3 — INFINITI QX60 2026 (Autopolis).", "Hoyo 5 — LEXUS UX 2026 (Cleber Lexus).", "Hoyo 7 — Carrito de Golf Club Car Tempo 2026.", "Hoyo 12 — Cadillac Optiq 2026.", "Hoyo 16 — XPENG G9 2026 (Cleber Xpeng).", "2° o más Hole In One: Socio — un año de cuotas de mantenimiento sin costo; Invitado — membresía anual de golf sin cuota de mantenimiento ($226,200 MXN, no transferible)."]}, {"categoria": "Mejor O´yes del Torneo", "premios": ["Sistema fotovoltaico Tigä de 20 paneles solares (12,000 W) — no aplica para Hole In One."]}]}', 5, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title = VALUES(title),
  content = VALUES(content),
  sort_order = VALUES(sort_order),
  enabled = VALUES(enabled);

INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'desempates', 'desempates', 'Desempates para Corte', '{"intro": "Lineamientos oficiales de desempate individual del V Torneo Anual Terralta 2026.", "paraTrofeos": ["Desempate por 1er lugar: se jugará en el campo, iniciando en el hoyo que designe el Comité. Solo habrá un ganador absoluto.", "En caso de triple empate o más, el 1er lugar se decide por juego en el campo; el 2°, 3° y demás posiciones por comparación de tarjetas.", "Si no hay luz natural o el clima lo impide, el 1er lugar se decide por comparación de tarjetas.", "En competencias Gross y Neto, solo el trofeo Gross va a juego en campo; el 1° Neto se decide por comparación de tarjetas."], "paraCorte": ["Para 2°, 3° y demás posiciones (trofeo Gross/Neto) y para el corte se aplica Regla 5A — Método de Comparación de Tarjetas:", "1) Mejor ronda del último día.", "2) Si persiste: mejor score hoyos 10–18, luego 13–18, luego 16–18 y por último hoyo 18.", "3) Si continúa: mismo procedimiento con hoyos 1–9.", "4) Si aún persiste: comparación hoyo por hoyo, del hoyo 18 hacia el hoyo 1.", "En categorías con hándicap: los desempates Neto se definen con score Neto y los Gross con score Gross, conservando la modalidad (Stroke Play o Stableford)."], "nota": "Una categoría se declara desierta con menos de 9 participantes (fecha límite jueves 25 de Junio 2026); el Comité podrá fusionarla con otra. Ronda estipulada: 9 hoyos. Ningún jugador podrá solicitar cambio de horario o día de juego."}', 6, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title = VALUES(title),
  content = VALUES(content),
  sort_order = VALUES(sort_order),
  enabled = VALUES(enabled);

INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'reglas', 'reglas', 'Reglas Locales', '{"items": [{"titulo": "Aviso a los Jugadores", "contenido": "Las reglas del Torneo serán las que rigen en la U.S.G.A. adoptadas por la Federación Mexicana de Golf y las locales del Club. Las condiciones de competencia y reglas locales se publicarán en las pantallas y se entregarán junto con las tarjetas de score. Las decisiones del Comité Organizador y del Comité de Reglas serán inapelables."}, {"titulo": "Modificaciones por Clima", "contenido": "Las rondas y días de juego están sujetas a cambios sin previo aviso para beneficio general del Torneo. En caso de condiciones climatológicas adversas, se tomará como primer criterio rondas de 9 hoyos cuando aplique."}, {"titulo": "Aceptación y Siembra de Jugadores", "contenido": "El Comité Organizador se reserva el derecho de aceptar a cualquier Jugador o sembrarlo en una categoría distinta. Jugador sin GHIN deberá firmar una carta donde acepte cualquier reclamación por parte de otro jugador y solo podrá participar por los premios de habilidades, los O´yes, los Hole In One y las rifas, renunciando a la competencia principal."}, {"titulo": "Entrega de Tarjetas", "contenido": "Los jugadores son responsables de entregar sus tarjetas firmadas y con el número de golpes sin ventajas (Gross) escritos claramente en cada casilla de los hoyos de la tarjeta oficial; deberán estar firmadas también por su anotador."}, {"titulo": "Verificación de Scores Anómalos", "contenido": "Si un Jugador tira en la suma de los dos días de competencia -8 golpes de su hándicap y existe una reclamación oficial y por escrito, el Comité Organizador investigará al jugador consultando las rondas registradas en el GHIN en Enero, Febrero, Marzo y Abril 2026. Si no tiene registrados scores suficientes que avalen un hándicap real y actualizado, podrá ser descalificado. La decisión del Comité de Reglas será definitiva."}, {"titulo": "Cortes — Avisos del Jugador", "contenido": "El Jugador que no pueda asistir a la ronda final tendrá que dar aviso a la Oficina de Golf o al Comité Organizador inmediatamente después de terminar su 2ª ronda para asignar su retiro y permitir el siguiente en lista. Si entregan la tarjeta y no se retira y luego no asiste a la final, ningún Jugador podrá tomar su lugar. Quien no avise será asignado por el Comité a la categoría que su hándicap original lo ubique, o a Senior si tiene 50 años o más."}, {"titulo": "Hole In One y O´yes", "contenido": "Habrá premios de Hole In One en los par 3: hoyos 3, 5, 7, 12 y 16. En caso de un 2° Hole In One en el mismo hoyo, se considerará como el mejor O´yes de 0.0 m; si hay un 3° en el mismo hoyo, el desempate lo ganará quien lo haga primero. Se premiará al mejor O´yes general de cada par 3 de todo el torneo (en caso de empate gana el primer tiro). Un jugador puede ganar dos o más O´yes con tiros diferentes. Los resultados pueden moverse hasta el último día. Las hojas firmadas por los jugadores de confirmación de distancia son inapelables."}, {"titulo": "Cierre de la Competencia", "contenido": "Se considera cerrada la competencia al iniciar la Ceremonia de Premiación (sábado 4 de Julio de 2026, 4:00 P.M. en Hoyo 19)."}], "reglamento": [{"titulo": "Sistemas de Juego — Stroke Play", "contenido": "CAMPEONATO, Premier y AA: 54 hoyos sin hándicap. Pasan el corte 12 jugadores (sin empates) después de 36 hoyos.\\n\\nCATEGORÍA A: 72 hoyos sin hándicap. Habrá 2 cortes: el primero a los 36 hoyos jugados pasando los mejores 24 jugadores sin empates y, el segundo corte, a 54 hoyos jugados pasando a la final los primeros 12 jugadores sin empates.\\n\\nCAMPEONATO MAYORES: 54 hoyos con hándicap al 80%. Pasan el corte los mejores 4 gross y los mejores 4 neto después de 36 hoyos. Los jugadores deberán tener 50 años o más cumplidos el primer día de juego.\\n\\nDAMAS A y B: 54 hoyos con el 80% de hándicap. Pasan el corte las mejores 4 gross y las mejores 4 neto después de 36 hoyos. En caso de que alguna jugadora pase a la final Gross y también a la final Neto, deberá jugar únicamente por el trofeo Gross; en este caso la quinta mejor jugadora en Neto, jugará por el trofeo Neto."}, {"titulo": "Sistemas de Juego — Stableford (acumulado)", "contenido": "DAMAS C, D y E: 54 hoyos con el 80% de hándicap. Habrá corte a los 36 hoyos jugados. Las mejores 8 jugadoras sin empates pasarán a la final conservando el acumulado de puntos.\\n\\nB, C y D: 72 hoyos con hándicap al 80%. Habrá 2 cortes: el primero a los 36 hoyos jugados pasando los mejores 24 jugadores sin empates y, el segundo corte, a 54 hoyos jugados pasando a la final los primeros 12 jugadores sin empates.\\n\\nSENIORS A y B: 54 hoyos con hándicap al 80%. Pasan el corte los mejores 12 jugadores de cada categoría después de 36 hoyos. Los jugadores deberán tener 60 o más años cumplidos al primer día de juego.\\n\\nDAMAS ESTELARES: 27 hoyos sin hándicap con corte a los 18 hoyos jugados pasando las mejores 6 jugadoras sin empates."}, {"titulo": "Marcas de Salida", "contenido": "CAMPEONATO: Negras.\\nPremier y AA: Azules.\\nA, B, C, D y CAMPEONATO MAYORES: Blancas.\\nDAMAS: Rojas.\\nDAMAS ESTELARES: Naranjas."}, {"titulo": "Hora de Salida", "contenido": "Tanto en stroke play como en stableford, los jugadores deberán estar en su mesa de salida, listos para jugar, a la hora estipulada independientemente del orden en que les toque salir. Si el jugador se presenta hasta con cinco minutos de retraso a su mesa de salida, tendrá 2 golpes de penalidad en el primer hoyo. Después de estos 5 minutos, será descalificado."}, {"titulo": "Ronda Estipulada", "contenido": "9 hoyos."}, {"titulo": "Vestimenta", "contenido": "Según el código interno del Reglamento de Golf."}, {"titulo": "Transportación Automotriz", "contenido": "Los jugadores podrán utilizar transportación automotriz para ellos mismos, su equipo y su caddie."}, {"titulo": "Caddie", "contenido": "Es obligatorio para todos los jugadores contratar los servicios de un caddie (siempre y cuando el club pueda proporcionarles uno), el cual puede ser compartido con otro jugador."}, {"titulo": "Puntuación Stableford", "contenido": "• 2 golpes más que el par (doble bogey): sin puntos\\n• 1 golpe más que el par (bogey): un punto\\n• Par: dos puntos\\n• 1 golpe menos que par (birdie): tres puntos\\n• 2 golpes menos que par (águila): cuatro puntos\\n• 3 golpes menos que par (albatros): cinco puntos"}, {"titulo": "Suspensión de Juego", "contenido": "• Suspensión inmediata del juego: una nota prolongada de sirena.\\n• Suspensión del juego: tres notas consecutivas de sirena.\\n• Reanudación del juego: dos notas consecutivas de sirena.\\n\\nCuando el juego ha sido suspendido por el Comité por una situación peligrosa (una nota prolongada de sirena), todos los jugadores deberán SUSPENDER DE INMEDIATO SU JUEGO. Si un jugador no interrumpe de inmediato su juego en esta circunstancia, será DESCALIFICADO."}, {"titulo": "Entrega de Scores", "contenido": "Es responsabilidad del jugador que su tarjeta sea entregada. Ésta deberá entregarse en un lapso no mayor a 15 minutos a partir del momento en el que el grupo haya terminado de jugar el último hoyo de la ronda. Las tarjetas se entregarán en la mesa de recepción ubicada junto a la caseta del starter. Si el jugador no entrega su tarjeta de score en el tiempo indicado será descalificado."}, {"titulo": "Cómo Decidir Empates — Para el Corte", "contenido": "Se tomará como primer criterio el mejor score de la última ronda. Si persistiera el empate, el segundo criterio será comparar el score de los hoyos del 10 al 18 de la última ronda, continuando con los hoyos del 13 al 18, 16 al 18 y por último el hoyo 18. En caso de persistir el empate se hará lo mismo con los hoyos del 1 al 9."}, {"titulo": "Cómo Decidir Empates — Para Trofeos", "contenido": "Sólo para el primer lugar en todas las categorías Gross o Neto se jugará a muerte súbita SIN VENTAJAS (en caso de no poder iniciar o continuar con un desempate a muerte súbita por oscuridad o mal clima, el desempate se llevará a cabo como lo señalado para desempatar para el corte). Para decidir el resto de los empates se utilizarán los mismos criterios que para el corte. Cualquier empate en el campo iniciará a la hora y por el hoyo establecidos por el Comité."}, {"titulo": "Premios de O’yes por Día", "contenido": "Importante: un jugador no podrá ganar más de un O’yes por día."}, {"titulo": "Cierre de la Competencia", "contenido": "Al iniciarse la ceremonia de premiación."}, {"titulo": "Recomendaciones", "contenido": "• Marcar la bola antes de levantarla para identificarla (penalidad: 1 golpe si no se marca).\\n• No hay \\"dadas\\", se debe embocar en todos los hoyos. En Stableford deberá embocarse toda bola que cuente para obtener puntos, de lo contrario podrá ser levantada sin embocar.\\n• No se debe cambiar bola en green (penalidad: un golpe).\\n• Máximo 14 bastones.\\n• No se puede dar ni pedir consejo.\\n• Presentarse en su hoyo de salida 5 minutos antes."}, {"titulo": "Aviso General", "contenido": "ESTAS REGLAS LOCALES Y TÉRMINOS DE LA COMPETENCIA DEJAN SIN EFECTO CUALQUIER REGLA LOCAL O TÉRMINO DE LA COMPETENCIA QUE EL CLUB UTILIZA PARA EL JUEGO NORMAL DE SUS SOCIOS, SE ENCUENTREN O NO PUBLICADAS EN CUALQUIER PARTE."}]}', 7, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title = VALUES(title),
  content = VALUES(content),
  sort_order = VALUES(sort_order),
  enabled = VALUES(enabled);

INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'competencias', 'competencias', 'Competencias Especiales', '{"items": [{"nombre": "Torneo de Driver de Distancia Caballeros", "descripcion": "Sistema de juego: tendrá solo el primer golpe en el Hoyo 1. Días de competencia: Viernes 26 de Junio al Viernes 3 de Julio. Categorías: Seniors, D, C, B, A, AA. Patrocinado por Dr. Gerardo González Saldívar y Technogym.", "premios": "Premio: Technogym Connected Dumbbells."}, {"nombre": "Torneo de Driver de Precisión Damas", "descripcion": "Sistema de juego: tendrá solo el primer golpe en el hoyo 10 de los tres días de la competencia. Días de competencia: Viernes 26, Lunes 29 de Junio y Miércoles 1 de Julio. Durante la ronda de juego — Hoyo 10.", "premios": "1°: $10,000 · 2°: $6,000 · 3°: $4,000 (en certificados de regalo Back 9)."}, {"nombre": "Torneo de Long Driver Caballeros", "descripcion": "Día de competencia: Jueves 2 de Julio (17:00 a 19:30 hrs). Lugar: Terraza Bar \\"La Vista\\". Patrocinado por Dr. Gerardo González Saldívar y Back 9 Golf.", "premios": "1°: $10,000 · 2°: $6,000 · 3°: $4,000 (en certificados de regalo Back 9)."}, {"nombre": "Torneo de Approach Mixto", "descripcion": "Calificación: Viernes 26 de Junio al Jueves 2 de Julio, 14:00–18:00 hrs en el Tee de Práctica. Cada jugador tendrá 3 oportunidades de hacer el mejor O´yes del día; calificarán los 7 mejores tiros (más cercanos) por día. En los 7 días calificarán 42 caballeros y 10 damas. Final: Viernes 3 de Julio, 20:30 hrs en Terraza Bar \\"La Vista\\". En la final cada participante realiza 3 tiros y cuenta el más cercano; en caso de empate, un tiro adicional define al ganador.", "premios": "1°: $10,000 · 2°: $6,000 · 3°: $4,000 (en certificados de regalo Back 9)."}, {"nombre": "Torneo de Putt Caballeros", "descripcion": "Calificación: Viernes 26, Sábado 27, Domingo 28 de Junio y Jueves 2 de Julio, 14:00–18:30 hrs en el Putting Green. Final: Viernes 3 de Julio, 18:00 hrs en el Putting Green.", "premios": "1°: $10,000 · 2°: $6,000 · 3°: $4,000 (en certificados de regalo Back 9)."}, {"nombre": "Torneo de Putt Damas", "descripcion": "Fecha: Lunes 29 de Junio, 16:00 hrs en el Putting Green.", "premios": "1°: $10,000 · 2°: $6,000 · 3°: $4,000 (en certificados de regalo Back 9)."}, {"nombre": "Premios O´yes", "descripcion": "Se premiarán los mejores O´yes diarios del torneo en los hoyos par 3: 3, 5, 7, 12 y 16. Un jugador puede ganar dos o más O´yes con tiros diferentes; en caso de empate, gana quien tiró primero.", "premios": "Premios diarios para los mejores O´yes en cada par 3. Mejor O´yes del Torneo: Sistema Fotovoltaico Tigä de 20 paneles solares (12,000 W) — no aplica para Hole In One."}]}', 8, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title = VALUES(title),
  content = VALUES(content),
  sort_order = VALUES(sort_order),
  enabled = VALUES(enabled);

