INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled)
VALUES (346, 'patrocinadoresOficiales', 'patrocinadores', 'Patrocinadores Oficiales', '{"items": [{"premio": "Hole In One — Hoyo 3 (Mayores de 18 años)", "patrocinador": "Autopolis Infiniti", "descripcion": "INFINITI QX60 2026 al primer Hole In One del torneo en el Hoyo 3."}, {"premio": "Hole In One — Hoyo 5 (Mayores de 18 años)", "patrocinador": "Cleber Lexus", "descripcion": "LEXUS UX 2026 al primer Hole In One del torneo en el Hoyo 5."}, {"premio": "Hole In One — Hoyo 7 (Mayores de 18 años)", "patrocinador": "Club Car", "descripcion": "Carrito de Golf Club Car Tempo 2026 al primer Hole In One del torneo en el Hoyo 7."}, {"premio": "Hole In One — Hoyo 12 (Mayores de 18 años)", "patrocinador": "Cadillac", "descripcion": "Cadillac Optiq 2026 al primer Hole In One del torneo en el Hoyo 12."}, {"premio": "Hole In One — Hoyo 16 (Mayores de 18 años)", "patrocinador": "Cleber Xpeng", "descripcion": "XPENG G9 2026 al primer Hole In One del torneo en el Hoyo 16."}, {"premio": "Premio de Hole In One General", "patrocinador": "Terralta A.C.", "descripcion": "$1,000,000 MXN al primer Hole In One en cualquiera de los 5 par 3. Si no se realiza, se rifa entre los jugadores inscritos durante la Ceremonia de Premiación (4 de Julio)."}, {"premio": "Mejor O´yes del Torneo", "patrocinador": "Tigä", "descripcion": "Sistema Fotovoltaico de 20 paneles solares — 12,000 W de potencia (incluye inversor, estructura, instalación, material eléctrico, ingeniería, app de monitoreo y trámite ante CFE). No aplica para Hole In One."}]}', 11, 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  title = VALUES(title),
  content = VALUES(content),
  sort_order = VALUES(sort_order),
  enabled = VALUES(enabled);
